 auto meter=[&](float level,int x){int count=int(juce::jlimit(0.f,1.f,(juce::Decibels::gainToDecibels(level,-60.f)+60)/60)*24);g.setColour(juce::Colour(0xff080909));g.fillRoundedRectangle(float(x-3),184,30,264,3);for(int i=0;i<24;++i)for(int c=0;c<2;++c){bool lit=i<count;g.setColour(juce::Colour(lit?(i>14?0xffff2017:0xffc8c2bb):0xff252424));g.fillRoundedRectangle(float(x+c*15),float(438-i*10.5f),10,5,1);}};
 meter(shownIn,79);meter(shownOut,971);
